#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    /* Length limit: 1024 characters (0x400). The original program used < 0x401 */
    if (strlen(s1) >= 1025 || strlen(s2) >= 1025) {
        puts("TOO_LONG");
        return 0;
    }
    int cnt1[256] = {0};
    int cnt2[256] = {0};
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c >= 'A' && c <= 'Z')
            c = (unsigned char)(c + 32); // tolower without locale
        cnt1[c]++;
    }
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c >= 'A' && c <= 'Z')
            c = (unsigned char)(c + 32);
        cnt2[c]++;
    }
    int anagram = 1;
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) {
            anagram = 0;
            break;
        }
    }
    puts(anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
